/* From Uiverse.io by victoryamaykin - Tags: switch */
.__UIV_SCOPE__ .switch {
 position: relative;
 display: inline-block;
 width: 120px;
 height: 34px;
}

.__UIV_SCOPE__ .switch input {
 display: none;
}

.__UIV_SCOPE__ .slider {
 position: absolute;
 cursor: pointer;
 top: 0;
 left: 0;
 right: 0;
 bottom: 0;
 background-color: #3C3C3C;
 -webkit-transition: .4s;
 transition: .4s;
 border-radius: 34px;
}

.__UIV_SCOPE__ .slider:before {
 position: absolute;
 content: "";
 height: 26px;
 width: 26px;
 left: 4px;
 bottom: 4px;
 background-color: white;
 -webkit-transition: .4s;
 transition: .4s;
 border-radius: 50%;
}

.__UIV_SCOPE__ input:checked + .slider {
 background-color: #0E6EB8;
}

.__UIV_SCOPE__ input:focus + .slider {
 box-shadow: 0 0 1px #2196F3;
}

.__UIV_SCOPE__ input:checked + .slider:before {
 -webkit-transform: translateX(26px);
 -ms-transform: translateX(26px);
 transform: translateX(85px);
}

/*------ ADDED CSS ---------*/
.__UIV_SCOPE__ .slider:after {
 content: 'DISABLED';
 color: white;
 display: block;
 position: absolute;
 transform: translate(-50%,-50%);
 top: 50%;
 left: 50%;
 font-size: 10px;
 font-family: Verdana, sans-serif;
}

.__UIV_SCOPE__ input:checked + .slider:after {
 content: 'ENABLED';
}

/*--------- END --------*/
